from datetime import datetime, timezone
import json
from pathlib import Path
import sqlite3

import config
import uniclubs_database
import uniclubs_export
import uniclubs_feed


TABLE_COLUMNS = {
    'clubs': uniclubs_export.CLUB_FIELDS,
    'events': uniclubs_export.EVENT_FIELDS,
    'import_log': ('id', 'imported_at_utc', 'status', 'event_count', 'message'),
}
TABLE_QUERIES = {
    'clubs': 'PRAGMA table_info(clubs)',
    'events': 'PRAGMA table_info(events)',
    'import_log': 'PRAGMA table_info(import_log)',
}


def _utc_now(now):
    """Validate an optional aware clock before opening or changing any files."""
    if now is None:
        return datetime.now(timezone.utc)
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be a timezone-aware datetime.')
    return now.astimezone(timezone.utc)


def _cache_path(path):
    """Reject runtime databases, published seeds and their symlink or hard-link aliases."""
    if not isinstance(path, (str, Path)) or not str(path).strip() or str(path) == ':memory:':
        raise ValueError('The public API cache requires a separate SQLite file path.')
    target = Path(path).resolve()
    protected = (config.DB_FILE, config.UNICLUBS_DB_FILE, config.UNICLUBS_USER_DB_FILE,
                 config.UNICLUBS_EXPORT_FILE, config.UNICLUBS_SQLITE, config.PUBLIC_UNISPORT_SEED)
    public_folder = (config.DATA_DIR / 'public').resolve()
    if target == public_folder or public_folder in target.parents:
        raise ValueError('The API cache must not replace a published public seed.')
    for source in protected:
        source = Path(source).resolve()
        if target == source or (target.exists() and source.exists() and target.samefile(source)):
            raise ValueError('The API cache must be separate from source and runtime files.')
    return target


def _read_seed():
    """Read and validate the bounded public JSON without consulting a local source database."""
    seed = Path(config.UNICLUBS_EXPORT_FILE)
    if seed.stat().st_size > config.UNICLUBS_MAX_EXPORT_BYTES:
        raise ValueError('The public UniClubs seed exceeds its size limit.')
    try:
        payload = json.loads(seed.read_text(encoding='utf-8'))
    except (ValueError, UnicodeDecodeError) as error:
        raise ValueError('The public UniClubs seed is not valid JSON.') from error
    return uniclubs_export.validate_export(payload)


def _check_schema(connection):
    """Refuse an existing database with foreign tables, private columns, views or triggers."""
    objects = connection.execute('''SELECT name, type FROM sqlite_master
        WHERE type IN ('table', 'view', 'trigger') AND name NOT LIKE 'sqlite_%' ''').fetchall()
    if not objects:
        return
    tables = set()
    for name, kind in objects:
        if kind != 'table' or name not in TABLE_COLUMNS:
            raise ValueError('The API cache path contains a different database.')
        tables.add(name)
        columns = tuple(row[1] for row in connection.execute(TABLE_QUERIES[name]).fetchall())
        if columns != TABLE_COLUMNS[name]:
            raise ValueError('The API cache must contain only the public catalog columns.')
    if tables != set(TABLE_COLUMNS):
        raise ValueError('The API cache has an incomplete public catalog schema.')


def _open_cache(target):
    """Open an established cache or restore an empty one, removing failed new files."""
    created = not target.exists()
    document = _read_seed() if created else None
    connection = None
    try:
        connection = uniclubs_database.get_connection(target)
        _check_schema(connection)
        uniclubs_database.init_db(connection)
        occupied = connection.execute('''SELECT EXISTS (SELECT 1 FROM clubs)
            OR EXISTS (SELECT 1 FROM events) OR EXISTS (SELECT 1 FROM import_log)''').fetchone()[0]
        if not occupied:
            if document is None:
                document = _read_seed()
            uniclubs_export.restore_export(connection, document)
        if uniclubs_feed.get_current_source_success(connection) is None:
            raise ValueError('The public API cache has no validated successful observation.')
        return connection, not occupied
    except (ValueError, OSError, sqlite3.Error):
        if connection is not None:
            connection.close()
        if created:
            target.unlink(missing_ok=True)
        raise


def _refresh_due(previous, now):
    """Check the local HTTP throttle independently from the publisher's source timestamp."""
    checked = previous.get('checked_at_utc')
    if checked is None:
        return True
    checked = datetime.fromisoformat(checked.replace('Z', '+00:00'))
    elapsed = (now - checked).total_seconds()
    return elapsed < 0 or elapsed >= config.UNICLUBS_FEED_CACHE_SECONDS


def _metadata(connection, previous, now, changed):
    """Expose only JSON-safe freshness and refresh metadata, without diagnostic messages."""
    source_success = uniclubs_feed.get_current_source_success(connection)
    observed = datetime.fromisoformat(source_success.replace('Z', '+00:00'))
    return {'available': True, 'source_success_utc': source_success,
            'refresh_ok': previous.get('refresh_ok', False),
            'stale': (now - observed).total_seconds() > config.UNICLUBS_FEED_STALE_SECONDS,
            'checked_at_utc': previous.get('checked_at_utc'), 'changed': changed}


def ensure_uniclubs(path, state=None, refresh=True, now=None):
    """Bootstrap a separate public cache and check its feed at most once per cache interval.

    :param path: separate writable SQLite cache file; source and private files are rejected
    :param state: optional persistent factory dictionary holding each path's last HTTP result
    :param refresh: False for an entirely offline call, which does not consume the HTTP interval
    :param now: optional timezone-aware datetime, normalized to UTC for deterministic checks
    :return: JSON-safe availability, source freshness, last check outcome and change metadata
    """
    checked = _utc_now(now)
    if state is None:
        state = {}
    if not isinstance(state, dict) or type(refresh) is not bool:
        raise ValueError('state must be a dictionary and refresh must be a boolean.')
    target = _cache_path(path)
    connection, restored = _open_cache(target)
    try:
        # Course: L04 – the factory owns the dictionary, so caches cannot share refresh outcomes.
        previous = {} if restored else state.get(str(target), {})
        changed = False
        if refresh and _refresh_due(previous, checked):
            result = uniclubs_feed.fetch_and_apply(connection, now=checked)
            previous = {'refresh_ok': result['ok'], 'checked_at_utc': result['checked_at_utc']}
            changed = result['changed']
        state[str(target)] = previous
        return _metadata(connection, previous, checked, changed)
    finally:
        connection.close()
